version.transform:
$$.specList.(
  $spec:= $;
  $qualityCheckFunction:= function($check, $values, $i){
    $check.type.id = "Number" ? (
      $numberValue := $lookup($values, $check.name)[$i] ~> $number;
      $not($isNilOrEmpty($check.lowerBound)) and $not($isNilOrEmpty($check.upperBound)) ?
        ($check.lowerBound ~> $number) <= $numberValue and $numberValue <= ($check.upperBound ~> $number)
      :
      $not($isNilOrEmpty($check.lowerBound)) ?
        ($check.lowerBound ~> $number) <= $numberValue
      :
      $not($isNilOrEmpty($check.upperBound)) ?
        $numberValue <= ($check.upperBound ~> $number)
      :
      $numberValue = ($check.expectedValue ~> $number)
    ) : 
    $check.type.id = "Boolean" ? (
      $lookup($values, $check.name)[$i] = $check.expectedValue
    ) : 
    $check.type.id = "String" ? (
      $lookup($values, $check.name)[$i] = $check.expectedValue
    ) : 
    $check.type.id = "Regex" ? (
      $contains($lookup($values, $check.name)[$i], $eval($check.expectedValue))
    )  
  };

  $$.action = "CREATE" ? (
    $sampleSize:= $$.sampleSize[$ != null] ~> $isArray ? $max($$.sampleSize) 
    : $$.sampleSize[$ != null] ~> $isNumber ? $$.sampleSize[$ != null];
    $not($isInteger($sampleSize)) and $isNotNilOrEmpty($sampleSize) ? 
      $throw("The sampleSize(s) can only be an integer.");
    $sampleIterator:= $isNotNilOrEmpty($sampleSize) ? [0..$sampleSize -1] : 0;
    $sampleIterator#$index.(      
      $spec.name in $keys($$.values) and $exists($lookup($$.values, $spec.name)[$index]) ? (
        {
          "create": 
            {
              "reportId": $$.reportId,
              "complete": true,
              "qualitySpecificationId": $spec.id,
              "result": $qualityCheckFunction($spec, $$.values, $index),
              "value": $lookup($$.values, $spec.name)[$index]
            }
        }
      ) : 
        {
          "create":
          {
            "reportId": $$.reportId,
            "complete": false,
            "qualitySpecificationId": $spec.id
          }
        }
    )
  ) :

  $$.action = "UPDATE" ? (
    $spec.(
      qualityChecks.edges[node.complete = false]#$index.node.(
        reportId != $$.reportId ? 
          $throw("The provided reportId does not match at least one of the quality checks to be updated");
        $checkId:= id;
        $spec.name in $keys($$.values) and $exists($lookup($$.values, $spec.name)[$index]) ? (
          {
            "update": 
              {
                "complete": true,
                "result": $qualityCheckFunction($spec, $$.values, $index),
                "value": $lookup($$.values, $spec.name)[$index]
              },
            "where": {
              "id": $checkId
            }
          }
        ) 
      )
    )
  ) : $throw("An appropriate action (CREATE/UPDATE) was not provided.")
)
